class MyUnpickler(pickle.Unpickler):
    def __init__(self, file, zf):
        super().__init__(file)
        self.zf = zf
    def find_class(self, module, name):
        if module == 'torch.storage' and name == '_get_storage_from_record':
            def f(key, numel, cls):
                k = key if key.startswith('simple_mnist/') else 'simple_mnist/' + key
                data = self.zf.read(k)
                return list(struct.unpack('<%df' % numel, data))
            return f
        if module == 'torch.storage' and name == '_load_from_bytes':
            def f(b):
